var a=`0827-chicken-tikka-masala`;var n=`world-0827`;var t=`IN`;var s=`south-asia`;var r=4;var g=114;var o={en:`Chicken Tikka Masala`,ua:`Курка тікка масала`};var l={en:`Chicken Tikka Masala is a India dish made with chicken thigh, plain yogurt, yellow onion, ginger-garlic paste. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Курка тікка масала, страва кухні країни Індія. Основні складники: куряче стегно, натуральний йогурт, жовта цибуля, імбирно-часникова паста. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 65 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 65 хвилин.`,t:[`marinating`],m:65,i:[[`chicken-thigh`,740,`g`],[`plain-yogurt`,150,`g`],[`garam-masala`,9,`g`],[`kashmiri-chili-powder`,6,`g`]]},{en:`Grill over medium-high heat for about 17 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 17 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:17,i:[[`canola-oil`,25,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,200,`g`],[`ginger-garlic-paste`,35,`g`],[`ground-cumin`,6,`g`],[`tomato-passata`,420,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 17 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 17 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:17,i:[[`heavy-cream`,170,`ml`],[`water`,100,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`]]}];var m={slug:a,id:n,country:`IN`,region:s,servings:4,minutes:114,title:o,text:l,steps:h};export{t as country,m as default,n as id,g as minutes,s as region,r as servings,a as slug,h as steps,l as text,o as title};